{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Inclusion criteria were as follows: (i) randomised controlled trials (RCTs), (ii) studies comparing 3D printing-assisted surgery to conventional surgery, (iii) treatment of fractures of the foot and/or ankle, (iv) published in 2012 or later, (v) outcome measures include at least 2 of: intraoperative blood loss, operation duration and fluoroscopy time. The following exclusion criteria were applied: (i) any other study type, (ii) non-English language, (iii) non-human studies, (iv) cadaveric studies, (v) studies investigating primarily patients with pathologies other than trauma (e.g. tumours, osteoporosis), (vi) studies published before 2012.",
      "reason": "The manuscript explicitly lists inclusion and exclusion criteria covering study design (RCTs), population (foot/ankle fractures), and specific outcome measures."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The following exclusion criteria were applied: (i) any other study type, (ii) non-English language, (iii) non-human studies, (iv) cadaveric studies, (v) studies investigating primarily patients with pathologies other than trauma (e.g. tumours, osteoporosis), (vi) studies published before 2012.",
      "reason": "The manuscript specifies language (English only) and publication date restrictions (2012 or later) as part of the exclusion criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly state whether studies were excluded because outcomes were not measured versus because results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "A metaanalysis of a subgroup of studies that reported quantitative data for the outcomes: operation duration, intraoperative blood loss, number of times fluoroscopy was used, and American Orthopaedic Foot and Ankle Society (AOFAS) Ankle-Hindfoot Rating System scores in control and 3D printing intervention groups were conducted in RevMan 5.3",
      "reason": "The manuscript specifies the groups used for synthesis (intervention vs control) and links them to the primary and secondary outcomes defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There are no notable restrictions on study eligibility that require a specific rationale beyond standard systematic review practice."
    }
  ],
  "confidence": 100
}

